using System;using System.Linq;using System.Globalization;using System.Collections.Generic;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class ProgramOfWorksForm {
 static BillQuantity SourceQuantity(string name,double value,string unit,bool basis=false){return new BillQuantity{Basis=basis,Section="Source",Description=name,Quantity=value,Unit=unit};}
 static List<BillQuantity> MergeSources(IEnumerable<BillQuantity> values){return values.Where(v=>Math.Abs(v.Quantity)>1e-10).GroupBy(v=>new{v.Description,v.Unit,v.Basis}).Select(g=>SourceQuantity(g.Key.Description,g.Sum(v=>v.Quantity),g.Key.Unit,g.Key.Basis)).ToList();}
 static string RebarSource(StockAllocation cut){return cut.Entry.Beam+" | "+cut.Entry.Description+(string.IsNullOrWhiteSpace(cut.Entry.ScheduleLabel)?"":" | "+cut.Entry.ScheduleLabel);}
 List<BillQuantity> TableSources(object[,] data,int quantityColumn,string unit,string prefix){var rows=new List<BillQuantity>();for(int n=0;n<data.GetLength(0);n++)rows.Add(SourceQuantity(prefix+Convert.ToString(data[n,1])+" | "+Convert.ToString(data[n,0]),Convert.ToDouble(data[n,quantityColumn]),unit));return MergeSources(rows);}
 List<BillQuantity> FixedQuantitySources(string key){
  if(key=="BeamConcrete"||key=="BeamForms")return TableSources(beam.ConcreteExcelRows(),key=="BeamConcrete"?4:7,key=="BeamConcrete"?"m3":"m2","Beam ");
  if(key=="SlabConcrete"||key=="SlabForms")return TableSources(slab.WorksMeasureRows(),key=="SlabConcrete"?4:7,key=="SlabConcrete"?"m3":"m2","Slab ");
  if(key=="FootingConcrete"||key=="FootingForms")return MergeSources(footingResults.Select(q=>SourceQuantity("Footing "+q.Id+" | "+q.Description,key=="FootingConcrete"?q.Concrete:q.Forms,key=="FootingConcrete"?"m3":"m2")));
  if(key=="ConcreteTotal"||key=="FormsTotal"){bool concrete=key=="ConcreteTotal";return MergeSources(FixedQuantitySources(concrete?"BeamConcrete":"BeamForms").Concat(FixedQuantitySources(concrete?"SlabConcrete":"SlabForms")).Concat(FixedQuantitySources(concrete?"FootingConcrete":"FootingForms")).Concat(canopyResults.Select(q=>SourceQuantity("Canopy / ledge "+q.Id+" | "+q.Description,concrete?q.Concrete:q.Forms,concrete?"m3":"m2"))));}
  if(key=="Grade40"||key=="Grade60"){int grade=key=="Grade40"?40:60;return MergeSources(projectRebarPlan.Where(a=>a.Demand.Grade==grade).Select(a=>SourceQuantity(RebarSource(a)+" | "+a.Demand.Diameter+"mm",a.Purchase,"kg")));}
  if(key=="WoodPaint")return MergeSources(openings.Where(o=>o.Wood).Select(o=>SourceQuantity(o.Id+" | "+o.Description,o.LeafPaint+o.JambPaint,"m2")));
  if(key=="Leversets"||key=="Hinges")return MergeSources(openings.Where(o=>o.Material!="Manual").Select(o=>SourceQuantity(o.Id+" | "+o.Description,key=="Hinges"?o.Hinges:o.Locks,"pcs")));
  if(key=="Plaster"||key=="MasonryPaint"){var results=key=="Plaster"?plasterResults:paintResults;return MergeSources(results.Select(p=>SourceQuantity(p.Key,p.Value.Net,"m2")));}
  string category=key=="WallTiles"?"Wall":key=="CeilingFinishes"?"Ceiling":key=="FloorFinishes"?"Floor":"";
  return MergeSources(finishItems.Where(f=>f.Category==category&&(key!="WallTiles"||f.Kind=="Tiles")).Select(f=>SourceQuantity(f.Id+" | "+f.Description,f.Total(FindWall(f.Wall),wallOpenings,finishItems),"m2")));
 }
 List<BillQuantity> MasonryQuantitySources(int index){var wallsOfType=index<2?RegularWalls.Where(w=>w.ThicknessMm==(index==0?100:150)):wallItems.Where(w=>w.Material==MasonryTotalNames[index-2]);return MergeSources(wallsOfType.Select(w=>SourceQuantity(w.Id+" | "+w.Description,w.Net(wallOpenings),"m2")));}
 List<BillQuantity> GravelQuantitySources(int index){var beamRows=TableSources(beam.EarthworkExcelRows(),10,"m3","Beam ");var footingRows=footingResults.Select(q=>SourceQuantity("Footing "+q.Id+" | "+q.Description,q.Gravel,"m3"));var manualRows=gravelEntries==null?Enumerable.Empty<BillQuantity>():gravelEntries.Rows.Cast<DataGridViewRow>().Where(r=>r.Tag is double).Select(r=>SourceQuantity(Cell(r,0)+" | "+Cell(r,1),(double)r.Tag,"m3"));var all=index==0?beamRows:index==1?footingRows:index==2?manualRows:beamRows.Concat(footingRows).Concat(manualRows);return MergeSources(all.Select(q=>SourceQuantity(q.Description,q.Quantity*(index==4?1+(double)gravelAllowance.Value/100:1),q.Unit)));}
 List<BillQuantity> EarthQuantitySources(int index){if(index==0||index==1)return MergeSources(earthSources.Select(q=>SourceQuantity(q.Source+" | "+q.Id,index==0?q.Bank:q.Fill,"m3")));if(index==3)return new List<BillQuantity>{SourceQuantity("External common borrow for the remaining compacted-space deficit",earthBalance.LooseCommonBorrow,"m3")};return MergeSources(earthBalance.Sources.Select(q=>SourceQuantity(q.Material.Source+" | "+q.Material.Id,index==2?q.LooseUsed:index==4?q.LooseSurplus:q.UnsuitableLoose,"m3")));}
 List<BillQuantity> MouldingQuantitySources(int index){return MergeSources(openings.Where(o=>o.Material!="Manual"&&o.Exterior&&(index==2||o.Kind==(index==0?"Door":"Window"))).Select(o=>SourceQuantity(o.Id+" | "+o.Description,o.MouldingLength,"lm")));}
 List<BillQuantity> CanopyQuantitySources(int index){if(index==4)return MergeSources(canopyPlan.Select(a=>SourceQuantity(RebarSource(a),a.Purchase,"kg")));return MergeSources(canopyResults.Select(q=>SourceQuantity(q.Id+" | "+q.Description,index==0?q.Concrete:index==1?q.SoffitForms:index==2?q.EdgeForms:q.Forms,index==0?"m3":"m2")));}
 List<BillQuantity> GridWeightSources(DataGridView grid,int column){return MergeSources(grid.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow&&Cell(r,grid.Columns.Count-1)=="Estimated").Select(r=>SourceQuantity(Cell(r,0)+" | "+Cell(r,1),Convert.ToDouble(r.Cells[column].Value,CultureInfo.InvariantCulture),"kg")));}
 List<BillQuantity> StockPurchaseSources(IEnumerable<SteelStock> stocks){return MergeSources(stocks.SelectMany(stock=>stock.Cuts.Select(cut=>SourceQuantity(cut.Demand.Member+" | "+stock.Specification,6*stock.KgM*cut.Demand.Length/stock.Net,"kg"))));}
 List<BillQuantity> SteelQuantitySources(string name){
  if(name=="Purlins net steel")return GridWeightSources(steelPurlins,7);if(name=="Angle bars net steel")return GridWeightSources(steelAngles,7);if(name=="Metal fascia net steel")return GridWeightSources(fasciaFrame,10);if(name=="Machine bolts shaft-only")return GridWeightSources(machineBolts,7);if(name=="Anchor bolts shaft-only")return GridWeightSources(anchorBolts,7);if(name=="Steel plates")return GridWeightSources(steelPlates,8);if(name=="Crossbracing rods")return GridWeightSources(crossBracing,9);
  if(name=="Steel plates PURCHASE weight")return GridWeightSources(steelPlates,11);if(name=="Steel plates final offcuts")return GridWeightSources(steelPlates,12);
  if(name=="6m stock PURCHASE weight")return StockPurchaseSources(steelStocks);
  if(name=="6m stock bars to buy (purlin/angle/fascia)")return steelStocks.GroupBy(s=>s.Specification).Select(g=>SourceQuantity(g.Key,g.Count(),"pcs")).ToList();
  if(name=="Final stock leftovers"||name=="Final stock leftover weight")return steelStocks.GroupBy(s=>s.Specification).Select(g=>SourceQuantity(g.Key,g.Sum(s=>s.Remaining*(name=="Final stock leftovers"?1:s.KgM)),name=="Final stock leftovers"?"m":"kg")).ToList();
  var nonStock=GridWeightSources(machineBolts,7).Concat(GridWeightSources(anchorBolts,7)).Concat(GridWeightSources(steelPlates,8)).Concat(GridWeightSources(crossBracing,9));if(name.StartsWith("TOTAL installed"))return MergeSources(GridWeightSources(steelPurlins,7).Concat(GridWeightSources(steelAngles,7)).Concat(GridWeightSources(fasciaFrame,10)).Concat(nonStock));if(name.StartsWith("TOTAL purchase"))return MergeSources(StockPurchaseSources(steelStocks).Concat(GridWeightSources(machineBolts,7)).Concat(GridWeightSources(anchorBolts,7)).Concat(GridWeightSources(steelPlates,11)).Concat(GridWeightSources(crossBracing,9)));
  if(name.StartsWith("Turnbuckles dia "))return MergeSources(crossBracing.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow&&Cell(r,12)=="Estimated"&&name=="Turnbuckles dia "+Number(r,5).ToString("0.###",CultureInfo.InvariantCulture)+"mm").Select(r=>SourceQuantity(Cell(r,0)+" | "+Cell(r,1),Count(r,6),"pcs")));
  return new List<BillQuantity>();
 }
 List<BillQuantity> RoofingQuantitySources(string name){var rows=new List<BillQuantity>();foreach(DataGridViewRow row in roofSheets.Rows){var q=row.Tag as RoofSheetQuantity;if(q==null)continue;if(name==RoofFamily(row)+" to buy")rows.Add(SourceQuantity(Cell(row,0)+" | "+Cell(row,1),q.BuyArea,"m2"));if(q.Insulation>0&&(name.StartsWith(Cell(row,11))||name=="Insulation total (net roof area)"))rows.Add(SourceQuantity(Cell(row,0)+" | "+Cell(row,1)+(name.EndsWith("net area")||name=="Insulation total (net roof area)"?"":" | net-area basis before whole-roll rounding"),q.Insulation,"m2",name.EndsWith("rolls to buy")||name.EndsWith("purchase coverage")));}foreach(DataGridViewRow row in roofAccessories.Rows){var q=row.Tag as RoofAccessoryQuantity;if(q==null)continue;string type=Cell(row,2);if(name==type||name==type+" pieces"||name==type+" sheet area")rows.Add(SourceQuantity(Cell(row,0)+" | "+Cell(row,1),name==type?q.BuyLength:name==type+" pieces"?q.Pieces:q.BuyArea,name==type?"m":name==type+" pieces"?"pcs":"m2"));}return MergeSources(rows);}
}
}
